class Solution {
public:
    int prefixConnected(vector<string>& words, int k) {
        unordered_map<string, int> freq;
        for (const string& w : words)
            if ((int)w.size() >= k) ++freq[w.substr(0, k)];
        int ans = 0;
        for (const auto& p : freq) if (p.second >= 2) ++ans;
        return ans;
    }
};
